import types
def _make_provider():
    provider = types.ModuleType("provider")
    class ProviderError(Exception): pass
    class UnknownCity(ProviderError): pass
    class Timeout(ProviderError): pass
    temps = {"durham": 21.5, "raleigh": 23.0, "cary": 22.1, "new york": 15.8}
    def get_temp(city):
        key = city.strip().lower()
        if key not in temps:
            raise UnknownCity(f"no data for {city!r}")
        return temps[key]
    class FlakyProvider:
        def __init__(self, fail_times=0):
            self.fail_times, self.calls = fail_times, 0
        def get_temp(self, city):
            self.calls += 1
            if self.calls <= self.fail_times:
                raise Timeout(f"timed out on call {self.calls}")
            return get_temp(city)
    for obj in (ProviderError, UnknownCity, Timeout, get_temp, FlakyProvider):
        setattr(provider, obj.__name__, obj)
    return provider
provider = _make_provider()
del _make_provider

