def repl_step(line, commands):
    global LAST_ERROR
    LAST_ERROR = None
    name, *args = line.split()
    if name not in commands:
        return f"unknown command: {name}"
    try:
        return str(commands[name](args))
    except Exception as e:
        LAST_ERROR = e
        return f"error: {type(e).__name__}: {e}"

