def load_config(text):
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ConfigError(f"invalid JSON: {e.msg}") from e
    try:
        data["model"]
    except KeyError:
        raise ConfigError("missing key: model") from None
    return data

